("sod_special_companion_apply_player_action",
 [
   (store_script_param, ":action", 1),
   (store_script_param, ":weight", 2),
   (try_begin),
     (call_script, "script_cf_sod_companion_in_main_party", "trp_diego_companion"),
     (assign, ":diego_delta", 0),
     (try_begin),
       (this_or_next|eq, ":action", sod_companion_action_free_captives),
       (this_or_next|eq, ":action", sod_companion_action_ymira_refugee_mercy),
       (this_or_next|eq, ":action", sod_companion_action_elephant_guard_support),
       (this_or_next|eq, ":action", sod_companion_action_jotnar_support),
       (eq, ":action", sod_companion_action_defeat_imperials),
       (store_mul, ":diego_delta", ":weight", 2),
       (val_add, "$g_sod_diego_anti_slaver_proof", ":weight"),
     (else_try),
       (this_or_next|eq, ":action", sod_companion_action_help_village),
       (this_or_next|eq, ":action", sod_companion_action_peaceful_desertion_allowed),
       (this_or_next|eq, ":action", sod_companion_action_petition_mediated),
       (this_or_next|eq, ":action", sod_companion_action_mutiny_negotiated),
       (eq, ":action", sod_companion_action_wounded_pay),
       (assign, ":diego_delta", ":weight"),
     (else_try),
       (this_or_next|eq, ":action", sod_companion_action_buy_slaves),
       (this_or_next|eq, ":action", sod_companion_action_carry_slaves),
       (this_or_next|eq, ":action", sod_companion_action_sell_prisoners),
       (this_or_next|eq, ":action", sod_companion_action_dirty_profit),
       (eq, ":action", sod_companion_action_diplomacy_betrayal),
       (store_mul, ":diego_delta", ":weight", -3),
       (assign, "$g_sod_diego_warning_pending", 1),
     (else_try),
       (this_or_next|eq, ":action", sod_companion_action_execute_lord),
       (this_or_next|eq, ":action", sod_companion_action_abuse_village),
       (this_or_next|eq, ":action", sod_companion_action_threatened_troops),
       (this_or_next|eq, ":action", sod_companion_action_mutiny_suppressed),
       (eq, ":action", sod_companion_action_peaceful_desertion_forbidden),
       (store_mul, ":diego_delta", ":weight", -2),
       (assign, "$g_sod_diego_warning_pending", 1),
     (try_end),
     (try_begin),
       (neq, ":diego_delta", 0),
       (troop_get_slot, ":approval", "trp_diego_companion", slot_troop_companion_approval),
       (val_add, ":approval", ":diego_delta"),
       (val_clamp, ":approval", 0, 101),
       (troop_set_slot, "trp_diego_companion", slot_troop_companion_approval, ":approval"),
       (call_script, "script_sod_companion_get_approval_band_to_reg", "trp_diego_companion"),
       (troop_set_slot, "trp_diego_companion", slot_troop_companion_trust_tier, reg0),
       (try_begin),
         (lt, ":approval", 5),
         (assign, "$g_sod_diego_warning_pending", 4),
       (else_try),
         (ge, ":approval", 45),
         (eq, "$g_sod_diego_warning_pending", 3),
         (assign, "$g_sod_diego_warning_pending", 0),
         (assign, "$g_sod_diego_reconciled", 1),
       (try_end),
     (try_end),
   (try_end),
 ]),

("sod_special_companion_recruit",
 [
   (store_script_param, ":companion", 1),
   (store_script_param, ":approval", 2),
   (store_script_param, ":role", 3),
   (try_begin),
     (is_between, ":companion", special_companions_begin, special_companions_end),
     (neg|call_script, "script_cf_sod_companion_in_main_party", ":companion"),
     (call_script, "script_recruit_troop_as_companion", ":companion"),
     (troop_set_slot, ":companion", slot_troop_companion_approval, ":approval"),
     (call_script, "script_sod_companion_get_approval_band_to_reg", ":companion"),
     (troop_set_slot, ":companion", slot_troop_companion_trust_tier, reg0),
     (call_script, "script_sod_special_companion_role_eligibility_to_reg", ":companion", ":role"),
     (try_begin),
       (eq, reg0, 1),
       (troop_set_slot, ":companion", slot_troop_companion_role, ":role"),
     (else_try),
       (troop_set_slot, ":companion", slot_troop_companion_role, sod_companion_role_none),
     (try_end),
     (troop_set_slot, ":companion", slot_troop_companion_personal_quest_stage, sod_companion_quest_trust_unlocked),
     (call_script, "script_sod_companion_sync_personal_quest_framework", ":companion"),
     (troop_set_slot, ":companion", slot_troop_companion_warning_state, sod_companion_warning_none),
     (troop_set_slot, ":companion", slot_troop_playerparty_history, pp_history_indeterminate),
     (troop_set_slot, ":companion", slot_troop_cur_center, -1),
     (assign, reg0, 1),
   (else_try),
     (assign, reg0, 0),
   (try_end),
 ]),

("sod_special_companion_role_eligibility_to_reg",
 [
   (store_script_param, ":companion", 1),
   (store_script_param, ":role", 2),
   (assign, reg0, 0),
   (try_begin),
     (eq, ":companion", "trp_diego_companion"),
     (this_or_next|eq, ":role", sod_companion_role_spymaster),
     (this_or_next|eq, ":role", sod_companion_role_scout),
     (eq, ":role", sod_companion_role_captain),
     (assign, reg0, 1),
   (try_end),
 ]),

