("sod_companion_try_cassian_mentor_arc_reactions",
 [
   (store_script_param, ":action", 1),
   (try_begin),
     (eq, ":action", sod_companion_action_cassian_last_order_sabotage),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc14"),
       (display_message, "@Lezalit approves Cassian's choice to turn old Imperial machinery against the Legion, though he notes that clean hands rarely win sieges.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc3"),
       (display_message, "@Ymira says Cassian has named people as instruments again, and that old orders do not become kinder because the target changed.", 0xCC6666),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc10"),
       (display_message, "@Bunduk mutters that officers always call it discipline when someone else pays the price.", 0xFFCC66),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc2"),
       (display_message, "@Marnid quietly asks who audits a secret network once it starts paying dividends.", 0xFFCC66),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc1"),
       (display_message, "@Borcha says a hidden road is useful, but every useful hidden road has two owners sooner or later.", 0xFFCC66),
     (try_end),
   (else_try),
     (eq, ":action", sod_companion_action_cassian_last_order_rescue),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc3"),
       (display_message, "@Ymira thanks Cassian for choosing names over numbers, and for once he does not correct her softness.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc10"),
       (display_message, "@Bunduk says rescuing old agents is the first officer's plan he has heard that remembers who bleeds.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc14"),
       (display_message, "@Lezalit warns that mercy without a perimeter is only sentiment with a casualty list.", 0xFFCC66),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc2"),
       (display_message, "@Marnid counts the cost of the rescue twice, then admits a debt paid in people may still be honest trade.", 0xFFCC66),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc1"),
       (display_message, "@Borcha likes the rescue route: dangerous, crooked, and just plain enough to work.", 0x99CCFF),
     (try_end),
   (else_try),
     (eq, ":action", sod_companion_action_cassian_last_order_expose),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc2"),
       (display_message, "@Marnid approves of dragging the ledger into daylight; fraud fears witnesses more than swords.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc1"),
       (display_message, "@Borcha says secrets are like bad bridges: useful until the wrong cart finds them.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc3"),
       (display_message, "@Ymira is relieved the old network will no longer swallow people quietly.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc10"),
       (display_message, "@Bunduk says public truth is late pay for old suffering, but late is better than never.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc14"),
       (display_message, "@Lezalit calls exposure strategically expensive and morally tidy, which is not quite praise.", 0xFFCC66),
     (try_end),
   (else_try),
     (eq, ":action", sod_companion_action_cassian_last_order_burn),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc3"),
       (display_message, "@Ymira watches Cassian burn the names and says some victories begin with refusing to own people.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc10"),
       (display_message, "@Bunduk approves of destroying a chain of command before it learns to call itself necessary.", 0x99CCFF),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc14"),
       (display_message, "@Lezalit is furious at the waste of intelligence, but not blind to the courage it took.", 0xCC6666),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc2"),
       (display_message, "@Marnid winces like a merchant watching a warehouse burn, even one full of stolen goods.", 0xCC6666),
     (try_end),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc1"),
       (display_message, "@Borcha says burning a map is sometimes wise, provided you remember where the traps were.", 0xFFCC66),
     (try_end),
   (try_end),
 ]),

