("sod_companion_process_departure_risk",
[
  (store_current_day, ":cur_day"),
  (try_for_range, ":companion", companions_begin, companions_end),
    (call_script, "script_cf_sod_companion_in_main_party", ":companion"),
    (neg|troop_slot_ge, ":companion", slot_troop_companion_loyalty_lock, 1),
    (troop_get_slot, ":approval", ":companion", slot_troop_companion_approval),
    (troop_get_slot, ":last_day", ":companion", slot_troop_companion_last_reaction_day),
    (store_sub, ":days_since", ":cur_day", ":last_day"),
    (try_begin),
      (troop_slot_eq, ":companion", slot_troop_companion_warning_state, sod_companion_warning_final),
      (lt, ":approval", 5),
      (ge, ":days_since", 7),
      (assign, "$npc_is_quitting", ":companion"),
      (troop_set_slot, ":companion", slot_troop_companion_last_reaction_day, ":cur_day"),
      (str_store_troop_name, s1, ":companion"),
      (display_message, "@{s1} has reached the end of patience and will confront you about leaving the company.", 0xCC3333),
    (else_try),
      (troop_slot_eq, ":companion", slot_troop_companion_warning_state, sod_companion_warning_acknowledged),
      (lt, ":approval", 10),
      (ge, ":days_since", 3),
      (troop_set_slot, ":companion", slot_troop_companion_warning_state, sod_companion_warning_final),
      (troop_set_slot, ":companion", slot_troop_companion_last_reaction_day, ":cur_day"),
      (call_script, "script_sod_companion_warning_to_s68", ":companion"),
      (display_message, "@Companion warning: {s68}", 0xCC6666),
      (str_store_troop_name, s1, ":companion"),
      (display_message, "@{s1} is near leaving the company. Speak with them directly before the road closes.", 0xCC3333),
    (try_end),
  (try_end),
]),

("sod_companion_try_trigger_reaction",
 [
   (store_script_param, ":companion", 1),
   (assign, reg0, 0),
   (try_begin),
     (is_between, ":companion", companions_begin, companions_end),
     (call_script, "script_cf_sod_companion_in_main_party", ":companion"),
     (store_current_day, ":cur_day"),
     (troop_get_slot, ":last_day", ":companion", slot_troop_companion_last_reaction_day),
     (store_sub, ":days_since", ":cur_day", ":last_day"),
     (try_begin),
       (this_or_next|ge, ":days_since", 3),
       (lt, ":last_day", 1),
       (troop_set_slot, ":companion", slot_troop_companion_last_reaction_day, ":cur_day"),
       (assign, reg0, 1),
     (try_end),
   (try_end),
 ]),

("sod_companion_advance_personal_quest",
 [
   (store_script_param, ":companion", 1),
   (store_script_param, ":outcome", 2),
   (try_begin),
     (is_between, ":companion", companions_begin, companions_end),
     (call_script, "script_cf_sod_companion_in_main_party", ":companion"),
     (troop_get_slot, ":stage", ":companion", slot_troop_companion_personal_quest_stage),
     (try_begin),
       (lt, ":stage", sod_companion_quest_trust_unlocked),
       (troop_set_slot, ":companion", slot_troop_companion_personal_quest_stage, sod_companion_quest_trust_unlocked),
       (call_script, "script_sod_companion_sync_personal_quest_framework", ":companion"),
     (else_try),
       (eq, ":stage", sod_companion_quest_trust_unlocked),
       (troop_set_slot, ":companion", slot_troop_companion_personal_quest_stage, sod_companion_quest_test_started),
       (call_script, "script_sod_companion_sync_personal_quest_framework", ":companion"),
     (else_try),
       (eq, ":stage", sod_companion_quest_test_started),
       (try_begin),
         (gt, ":outcome", 0),
         (troop_set_slot, ":companion", slot_troop_companion_personal_quest_stage, sod_companion_quest_resolved_good),
         (troop_set_slot, ":companion", slot_troop_companion_loyalty_lock, 1),
         (call_script, "script_sod_companion_shift_approval", ":companion", 12),
         (call_script, "script_sod_companion_sync_personal_quest_framework", ":companion"),
       (else_try),
         (troop_set_slot, ":companion", slot_troop_companion_personal_quest_stage, sod_companion_quest_resolved_hard),
         (call_script, "script_sod_companion_shift_approval", ":companion", -8),
         (call_script, "script_sod_companion_apply_hard_compromise_payoff", ":companion"),
         (call_script, "script_sod_companion_sync_personal_quest_framework", ":companion"),
       (try_end),
     (try_end),
   (try_end),
 ]),

