("sod_companion_describe_company_depth_to_s30",
 [
   (assign, ":present", 0),
   (assign, ":devoted", 0),
   (assign, ":loyal", 0),
   (assign, ":steady", 0),
   (assign, ":wary", 0),
   (assign, ":troubled", 0),
   (assign, ":warnings", 0),
   (assign, ":roles", 0),
   (assign, ":strained_roles", 0),
   (assign, ":best_approval", -1),
   (assign, ":best_companion", -1),
   (assign, ":worst_approval", 101),
   (assign, ":worst_companion", -1),
   (try_for_range, ":companion", companions_begin, special_companions_end),
     (call_script, "script_cf_sod_companion_in_main_party", ":companion"),
     (val_add, ":present", 1),
     (troop_get_slot, ":approval", ":companion", slot_troop_companion_approval),
     (try_begin),
       (gt, ":approval", ":best_approval"),
       (assign, ":best_approval", ":approval"),
       (assign, ":best_companion", ":companion"),
     (try_end),
     (try_begin),
       (lt, ":approval", ":worst_approval"),
       (assign, ":worst_approval", ":approval"),
       (assign, ":worst_companion", ":companion"),
     (try_end),
     (call_script, "script_sod_companion_get_approval_band_to_reg", ":companion"),
     (try_begin),
       (eq, reg0, sod_companion_approval_devoted),
       (val_add, ":devoted", 1),
     (else_try),
       (eq, reg0, sod_companion_approval_loyal),
       (val_add, ":loyal", 1),
     (else_try),
       (eq, reg0, sod_companion_approval_steady),
       (val_add, ":steady", 1),
     (else_try),
       (eq, reg0, sod_companion_approval_wary),
       (val_add, ":wary", 1),
     (else_try),
       (val_add, ":troubled", 1),
     (try_end),
     (try_begin),
       (troop_slot_eq, ":companion", slot_troop_companion_warning_state, sod_companion_warning_pending),
       (val_add, ":warnings", 1),
     (try_end),
   (try_end),
   (try_for_range, ":companion", companions_begin, special_companions_end),
     (call_script, "script_cf_sod_companion_in_main_party", ":companion"),
     (troop_slot_ge, ":companion", slot_troop_companion_role, 1),
     (troop_get_slot, ":approval", ":companion", slot_troop_companion_approval),
     (try_begin),
       (ge, ":approval", 45),
       (val_add, ":roles", 1),
     (else_try),
       (val_add, ":strained_roles", 1),
     (try_end),
   (try_end),
   (try_begin),
     (gt, ":best_companion", -1),
     (str_store_troop_name, s31, ":best_companion"),
   (else_try),
     (str_store_string, s31, "@No companion"),
   (try_end),
   (try_begin),
     (gt, ":worst_companion", -1),
     (str_store_troop_name, s32, ":worst_companion"),
   (else_try),
     (str_store_string, s32, "@No companion"),
   (try_end),
   (assign, reg30, ":present"),
   (assign, reg31, ":devoted"),
   (assign, reg32, ":loyal"),
   (assign, reg33, ":steady"),
   (assign, reg34, ":wary"),
   (assign, reg35, ":troubled"),
   (assign, reg36, ":warnings"),
   (assign, reg37, ":roles"),
   (assign, reg38, ":strained_roles"),
  (str_store_string, s30, "@Companion approval^^Present: {reg30}^Devoted: {reg31}; loyal: {reg32}; steady: {reg33}; wary: {reg34}; troubled or worse: {reg35}.^Effective camp offices: {reg37}; strained offices: {reg38}. Pending warning talks: {reg36}.^Strongest loyalty: {s31}. Sharpest doubt: {s32}.^Personal leads: Borcha watches the roads you choose; Marnid watches the price you make others pay; Ymira watches your mercy toward captives; Firentis watches whether penance becomes purpose; Lezalit watches whether discipline becomes strength or cruelty."),
 ]),

("sod_companion_describe_role_offices_to_s31",
 [
 (str_store_string, s31, "@Scout office: while Borcha serves as Scout and trusts the company, his roadcraft steadies morale and bleeds a little pressure from Black Khergit routes each day. If The Road Keeps Its Own ends well, that pressure work improves.^Quartermaster office: Marnid turns waste into order. If trusted, he gives the company a steadier camp mood; if The Honest Price ends cleanly, the effect improves.^Surgeon office: Ymira steadies the wounded and the frightened. If Mercy Under Arms ends well, the company takes deeper heart from her care.^Envoy and Captain office: Rolf lends public presence, ceremony, and improbable confidence. If A Name Worth Wearing ends well, his reputation steadies the camp further.^Scout and Captain office: Baheshtur reads open ground, rider pride, and horde pressure. If The Unbroken Saddle ends well, his chosen loyalty steadies the camp further.^Captain and Envoy office: Firentis steadies discipline when restraint matters. If Debt of the Sword ends well, his service gives the company deeper heart.^Surgeon and Envoy office: Jeremus keeps wounds, peace, and restraint in the company mind. If Hands That Will Not Harden ends well, his care steadies the camp further.^Captain and Quartermaster office: Bunduk keeps officer pride from spending ordinary soldiers too cheaply. If The Men Who Hold the Line ends well, his line steadies the camp further.^Quartermaster and Surgeon office: Katrin keeps supper, wages, and clean cloth from becoming heroic afterthoughts. If The Last Coin in Camp ends well, her practical care steadies the camp further.^Captain office: Matheld turns fear into a shield wall and courage into noise enemies can hear. If No Backward Step ends well, her courage steadies the camp further.^Envoy and Captain office: Alayen makes the standard mean obligation, not vanity. If The Standard and the Self ends well, his honor steadies the camp further.^Captain and Scout office: Nizar turns daring into morale and pursuit. If The Impossible Charge ends well, his courage steadies the camp further.^Captain office: Lezalit turns fear into formation. If Discipline Without Chains ends well, his training steadies the company further.^Engineer and Quartermaster office: Artimenner turns plans, tools, and tolerances into fewer preventable disasters. If The Siege That Should Have Worked ends well, his engineering steadies the camp further.^Scout and Spymaster office: Deshavi watches hunger, tracks, and slaver signs before they reach camp. If Tracks Through Ash ends well, her under-road warnings improve.^Spymaster office: Klethi opens quiet routes and closes dangerous ones. If A Knife With a Name ends well, her underworld work cuts more horde pressure."),
 ]),

("sod_diego_companion_describe_to_s34",
 [
   (str_store_string, s34, "@"),
   (try_begin),
     (call_script, "script_cf_sod_companion_in_main_party", "trp_diego_companion"),
     (faction_get_slot, reg1, "fac_sod_merc_guild6", slot_faction_slaver_market_heat),
     (faction_get_slot, reg2, "fac_sod_merc_guild6", slot_faction_slaver_market_supply),
     (faction_get_slot, reg3, "fac_sod_merc_guild6", slot_faction_slaver_market_demand),
     (assign, reg4, "$g_sod_diego_anti_slaver_proof"),
     (troop_get_slot, reg5, "trp_diego_companion", slot_troop_companion_approval),
     (str_store_string, s33, "@"),
     (try_begin),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc3"),
       (str_store_string, s33, "@ Ymira's mercy gives his anger somewhere human to stand."),
     (else_try),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc10"),
       (str_store_string, s33, "@ Bunduk's soldier sense earns his quiet respect."),
     (else_try),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc12"),
       (str_store_string, s33, "@ Jeremus reminds him that rescue is not finished until wounds are tended."),
     (else_try),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc14"),
       (str_store_string, s33, "@ Lezalit's talk of discipline makes him listen for chains under cleaner words."),
     (else_try),
       (call_script, "script_cf_sod_companion_in_main_party", "trp_npc2"),
       (str_store_string, s33, "@ Marnid's ledgers make him wary whenever profit stands too near a cage."),
     (try_end),
     (try_begin),
       (lt, reg5, 30),
       (str_store_string, s34, "@^Diego: He still watches the prisoner line, but he no longer trusts your hand on the lock. Slaver heat {reg1}, supply {reg2}, demand {reg3}. Chainbreaker work is disabled until the command proves it breaks cages instead of buying them.{s33}"),
     (else_try),
       (eq, "$g_sod_diego_warning_pending", 1),
       (str_store_string, s34, "@^Diego: He keeps apart from the fire. Slaver heat {reg1}, supply {reg2}, demand {reg3}. He has words waiting about chains sold or runaways returned.{s33}"),
     (else_try),
       (eq, "$g_sod_diego_reconciled", 1),
       (str_store_string, s34, "@^Diego: He watches the prisoner line, but not with doubt now. Slaver heat {reg1}, supply {reg2}, demand {reg3}. Chainbreaker proof {reg4}. He believes this company can break cages and keep moving.{s33}"),
     (else_try),
       (str_store_string, s34, "@^Diego: He sits where he can see the road and the prisoner line. Slaver heat {reg1}, supply {reg2}, demand {reg3}. His Chainbreaker work can turn some freed captives into grateful followers when there is room in the company.{s33}"),
     (try_end),
   (try_end),
 ]),

