("sod_companion_qa_recruit_roster",
 [
   (try_begin),
     (eq, "$g_sod_debug", 1),
     (try_for_range, ":companion", companions_begin, companions_end),
       (try_begin),
         (neg|call_script, "script_cf_sod_companion_in_main_party", ":companion"),
         (party_add_members, "p_main_party", ":companion", 1),
       (try_end),
       (troop_set_slot, ":companion", slot_troop_companion_approval, 60),
       (call_script, "script_sod_companion_get_approval_band_to_reg", ":companion"),
       (troop_set_slot, ":companion", slot_troop_companion_trust_tier, reg0),
       (troop_set_slot, ":companion", slot_troop_companion_personal_quest_stage, sod_companion_quest_trust_unlocked),
       (call_script, "script_sod_companion_sync_personal_quest_framework", ":companion"),
     (try_end),
     (party_add_prisoners, "p_main_party", "trp_slave", 3),
     (party_add_prisoners, "p_main_party", "trp_slave_female", 3),
     (party_add_members, "p_main_party", "trp_swadian_recruit", 8),
     (display_message, "@QA: companion roster recruited, trust opened, captives and recruits added.", debug_color),
   (try_end),
 ]),

